<?php $admin_title='Products';include '_header.php';$products=$pdo->query("SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.updated_at DESC,p.id DESC")->fetchAll();$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$active=array_filter($products,fn($x)=>$x['status']==='active');$sold=array_filter($products,fn($x)=>$x['status']==='sold');$archived=array_filter($products,fn($x)=>$x['status']==='archived');?><div class="inventory-summary"><div class="inventory-mini"><i class="fa-solid fa-boxes-stacked"></i><div><span>Active products</span><strong><?=count($active)?></strong></div></div><div class="inventory-mini"><i class="fa-solid fa-circle-check"></i><div><span>Available units</span><strong><?=array_sum(array_column($active,'quantity'))?></strong></div></div><div class="inventory-mini"><i class="fa-solid fa-bag-shopping"></i><div><span>Sold products</span><strong><?=count($sold)?></strong></div></div><div class="inventory-mini"><i class="fa-solid fa-box-archive"></i><div><span>Archived</span><strong><?=count($archived)?></strong></div></div></div><div class="panel"><div class="panel-head"><div><h2>Product Catalogue</h2><small class="muted">Add products, monitor stock, mark sold items and archive old catalogue entries.</small></div><button class="btn btn-primary" onclick="$('#productModal').addClass('open')"><i class="fa-solid fa-plus"></i> Add Product</button></div><div class="product-admin-grid"><?php foreach($products as $p):?><article class="product-admin-card"><div class="product-admin-image"><img src="<?=e($p['image_url']?:'../assets/img/favicon.png')?>" alt="<?=e($p['name'])?>"><span class="badge <?=$p['status']==='sold'?'amber':($p['status']==='archived'?'red':($p['quantity']<=$p['minimum_stock']?'amber':'green'))?>"><?=e(ucfirst($p['status']))?></span></div><div class="product-admin-body"><span class="product-meta"><?=e($p['category']??'Uncategorised')?> · <?=e($p['sku'])?></span><h3><?=e($p['name'])?></h3><div class="product-facts"><span><b><?=$p['quantity']?></b> <?=e($p['unit'])?></span><span><b>K<?=number_format($p['selling_price'],2)?></b> sell</span><span><b><?=$p['minimum_stock']?></b> reorder</span></div><div class="card-actions"><?php if($p['status']==='active'):?><button class="btn btn-soft product-status" data-id="<?=$p['id']?>" data-action="sold"><i class="fa-solid fa-cart-shopping"></i> Mark Sold</button><button class="btn btn-danger product-status" data-id="<?=$p['id']?>" data-action="archive"><i class="fa-solid fa-box-archive"></i></button><?php else:?><button class="btn btn-soft product-status" data-id="<?=$p['id']?>" data-action="restore"><i class="fa-solid fa-rotate-left"></i> Restore</button><?php endif;?></div></div></article><?php endforeach;?></div></div><div class="modal" id="productModal"><div class="modal-card"><div class="panel-head"><h2>Add Product</h2><button class="btn btn-ghost" onclick="$('#productModal').removeClass('open')"><i class="fa-solid fa-xmark"></i></button></div><form class="ajax-form" action="api/save_product.php" method="post" enctype="multipart/form-data" data-reload="1"><input type="hidden" name="csrf" value="<?=token()?>"><div class="form-grid"><div class="form-group"><label>Product name</label><input class="form-control" name="name" data-required data-message="Enter the product name." placeholder="e.g. Sugar 2kg"></div><div class="form-group"><label>SKU</label><input class="form-control" name="sku" data-required data-message="Enter a unique product code." placeholder="GRO-001"></div><div class="form-group"><label>Category</label><select class="form-control" name="category_id" data-required data-message="Choose a category."><option value="">Choose category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Unit</label><input class="form-control" name="unit" data-required data-message="Enter a stock unit." placeholder="Pack / Bottle / Bag"></div><div class="form-group"><label>Buying price</label><input class="form-control" type="number" min="0" step="0.01" name="buying_price" data-required></div><div class="form-group"><label>Selling price</label><input class="form-control" type="number" min="0" step="0.01" name="selling_price" data-required></div><div class="form-group"><label>Opening stock</label><input class="form-control" type="number" min="0" name="quantity" data-required></div><div class="form-group"><label>Minimum stock</label><input class="form-control" type="number" min="0" name="minimum_stock" data-required></div><div class="form-group full"><label>Description</label><textarea class="form-control" name="description" placeholder="Short product description"></textarea></div><div class="form-group"><label>Image URL</label><input class="form-control" name="image_url" placeholder="https://..."></div><div class="form-group"><label>Or upload image</label><input class="form-control" type="file" name="image" accept="image/*"></div><div class="form-group"><label><input type="checkbox" name="featured" value="1"> Featured product</label></div></div><div class="modal-actions"><button type="button" class="btn btn-ghost" onclick="$('#productModal').removeClass('open')">Cancel</button><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Save Product</button></div></form></div></div><script>$(document).on('click','.product-status',function(){const b=$(this),action=b.data('action'),id=b.data('id');Swal.fire({title:action==='sold'?'Mark product as sold?':action==='archive'?'Archive this product?':'Restore this product?',text:action==='sold'?'Remaining stock will be moved out and the item will appear as sold.':'You can restore archived products later.',icon:'question',showCancelButton:true,confirmButtonText:'Continue'}).then(r=>{if(!r.isConfirmed)return;$.post('api/product_status.php',{id,action,csrf:window.csrfToken}).done(x=>{Toastify({text:x.message,duration:2500,gravity:'top',position:'right'}).showToast();if(x.ok)setTimeout(()=>location.reload(),400)})})})</script><?php include '_footer.php'; ?>